public static AAXBOMCalcCompletedBusinessEventContract newFromBOMCalcTable(BOMCalcTable _bomCalcTable)
{
    var contract = new AAXBOMCalcCompletedBusinessEventContract();
    contract.initialize(_bomCalcTable);

    return contract;
}

